package com.dolphin.oemhud;import android.os.Bundle;import android.content.*;public class BridgeFlowRuntimeSimulation{public static void main(String[]args){BridgeService bridge=new BridgeService();bridge.getSharedPreferences(BridgeLog.STORE,0).edit().putBoolean("enabled",true).apply();bridge.onCreate();Bundle b=new Bundle();b.putInt("KEY_TYPE",10001);b.putInt("NEW_ICON",5);b.putInt("SEG_REMAIN_DIS_AUTO",300);Intent i=new Intent().setAction("AUTONAVI_STANDARD_BROADCAST_SEND");i.putExtra("KEY_TYPE",10001);i.putExtra("NEW_ICON",5);i.putExtra("SEG_REMAIN_DIS_AUTO",300);bridge.registered.onReceive(bridge,i);System.out.println("SIM1 broadcast received: cueRecords="+BridgeLog.cues+"; hudSendAttempts="+HudConnector.attempted);NavCue raw=NavCue.fromAutonavi(b);System.out.println("SIM2 decoded direction="+raw.direction+" icon="+raw.icon+" meters="+raw.distanceMeters+" encoded="+(MconHudQProtocol.fromCue(raw)==null?"NULL":MconHudQProtocol.hex(MconHudQProtocol.fromCue(raw))));NavCue text=NavCue.fromText("순정내비 알림","300m 앞에서 우회전");BridgeLog.cue(bridge,text);if(HudConnector.sent<2)throw new AssertionError("end-to-end simulated HUD packets missing");System.out.println("SIM3 notification path: cueRecords="+BridgeLog.cues+"; hudSendAttempts="+HudConnector.attempted+" hudPackets="+HudConnector.sent);bridge.onDestroy();}}